function testftp(form) {
  fetch('installer.php?ftphost=' + encodeURIComponent(form.ftp_host.value))
    .then((r) => r.text())
    .then((result) => {
      var results = eval('(' + result + ')');
      document.getElementById('ftp-test-results').innerHTML = results.message;
    });
}
